screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブルインデックスの取得
  const clientTableIdx = tables.findIndex(t => t.tableName === 'クライアント');
  const historyTableIdx = tables.findIndex(t => t.tableName === '対応履歴');
  const policyTableIdx = tables.findIndex(t => t.tableName === 'クライアント_対応方針');
  const dealTableIdx = tables.findIndex(t => t.tableName === '受注');
  const projectTableIdx = tables.findIndex(t => t.tableName === '案件');

  let selectedClientId = null;
  let allClients = [];
  let allHistories = [];
  let allPolicies = [];
  let allDeals = [];
  let allProjects = [];

  // ===== 1. 初期データ読み込み =====
  async function loadAllData() {
    if (clientTableIdx >= 0) allClients = await window.aivicApi.list(clientTableIdx) || tables[clientTableIdx].records || [];
    if (historyTableIdx >= 0) allHistories = await window.aivicApi.list(historyTableIdx) || tables[historyTableIdx].records || [];
    if (policyTableIdx >= 0) allPolicies = await window.aivicApi.list(policyTableIdx) || tables[policyTableIdx].records || [];
    if (dealTableIdx >= 0) allDeals = await window.aivicApi.list(dealTableIdx) || tables[dealTableIdx].records || [];
    if (projectTableIdx >= 0) allProjects = await window.aivicApi.list(projectTableIdx) || tables[projectTableIdx].records || [];

    renderKPIs();
    renderCharts();
    renderClientList();
  }

  // ===== 2. KPI 計算・表示 =====
  function renderKPIs() {
    // 今月受注額
    const now = new Date();
    const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthRevenue = allDeals
      .filter(d => d.受注日 && d.受注日.startsWith(currentMonth) && d.税込金額)
      .reduce((sum, d) => sum + (parseInt(d.税込金額) || 0), 0);
    container.querySelector('[data-testid="kpi-revenue"]').textContent = `¥${monthRevenue.toLocaleString()}`;

    // 対応中案件
    const activeDeals = allProjects.filter(p => p.ステータス && ['新規', '進行中', '提案済み'].includes(p.ステータス)).length;
    container.querySelector('[data-testid="kpi-active-deals"]').textContent = activeDeals;

    // クライアント数
    container.querySelector('[data-testid="kpi-client-count"]').textContent = allClients.length;
  }

  // ===== 3. チャート描画 =====
  function renderCharts() {
    // 月別受注額推移（過去12ヶ月）
    const monthlyRevenue = {};
    const now = new Date();
    for (let i = 11; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      monthlyRevenue[key] = 0;
    }
    allDeals.forEach(deal => {
      if (deal.受注日 && deal.税込金額) {
        const month = deal.受注日.slice(0, 7);
        if (monthlyRevenue.hasOwnProperty(month)) {
          monthlyRevenue[month] += parseInt(deal.税込金額) || 0;
        }
      }
    });
    const labels = Object.keys(monthlyRevenue);
    const data = Object.values(monthlyRevenue);

    const ctxRevenue = container.querySelector('#chart-revenue').getContext('2d');
    new window.Chart(ctxRevenue, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: '受注額',
          data: data,
          borderColor: '#ffa500',
          backgroundColor: 'rgba(255,165,0,0.08)',
          borderWidth: 2,
          tension: 0.3,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: '#ffa500'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: {
          y: { beginAtZero: true, ticks: { callback: v => `¥${(v/1000000).toFixed(0)}M` } }
        }
      }
    });

    // 案件ステータス分布
    const statusCounts = {};
    allProjects.forEach(p => {
      const status = p.ステータス || '不明';
      statusCounts[status] = (statusCounts[status] || 0) + 1;
    });
    const statusLabels = Object.keys(statusCounts);
    const statusData = Object.values(statusCounts);
    const colors = ['#ffa500', '#ff6464', '#64b5ff', '#64ff96', '#d0a0ff'];

    const ctxStatus = container.querySelector('#chart-status').getContext('2d');
    new window.Chart(ctxStatus, {
      type: 'doughnut',
      data: {
        labels: statusLabels,
        datasets: [{
          data: statusData,
          backgroundColor: colors.slice(0, statusLabels.length)
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { position: 'bottom', labels: { font: { size: 11 } } } }
      }
    });
  }

  // ===== 4. クライアント一覧描画 =====
  function renderClientList(filter = '') {
    const list = container.querySelector('#client-list');
    const filtered = allClients.filter(c => 
      !filter || c.クライアント名?.includes(filter) || c.メールアドレス?.includes(filter)
    );

    list.innerHTML = filtered.map(client => `
      <div 
        data-client-id="${client.クライアントID}" 
        style="padding: 8px; border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s; background: ${selectedClientId === client.クライアントID ? 'rgba(255,165,0,0.15)' : 'transparent'};"
        class="client-item"
      >
        <div style="font-weight: 600; color: var(--text); margin-bottom: 2px;">${client.クライアント名 || '-'}</div>
        <div style="font-size: 11px; color: var(--text-muted);">${client.業種 || '-'}</div>
        <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">${client.メールアドレス || '-'}</div>
      </div>
    `).join('');

    // クライアント項目クリックイベント
    container.querySelectorAll('.client-item').forEach(item => {
      item.addEventListener('click', () => {
        selectedClientId = item.dataset.clientId;
        renderClientList(filter);
        renderClientDetail();
      });
    });
  }

  // ===== 5. クライアント詳細表示 =====
  function renderClientDetail() {
    const client = allClients.find(c => c.クライアントID === selectedClientId);
    const detailPanel = container.querySelector('#client-detail-panel');
    const historyPanel = container.querySelector('#history-panel');
    const policyPanel = container.querySelector('#policy-panel');
    const dealsPanel = container.querySelector('#deals-panel');

    if (!client) {
      detailPanel.style.display = 'none';
      historyPanel.style.display = 'none';
      policyPanel.style.display = 'none';
      dealsPanel.style.display = 'none';
      return;
    }

    // 詳細パネル表示
    detailPanel.style.display = 'block';
    container.querySelector('#detail-name').textContent = client.クライアント名 || '-';
    container.querySelector('#detail-industry').textContent = client.業種 || '-';
    container.querySelector('#detail-rep').textContent = client.代表者名 || '-';
    container.querySelector('#detail-email').textContent = client.メールアドレス || '-';
    container.querySelector('#detail-status').textContent = client.ステータス || '-';
    container.querySelector('#detail-last-contact').textContent = client.最終接触日 ? client.最終接触日.slice(0, 10) : '-';
    container.querySelector('#detail-revenue').textContent = `¥${(parseInt(client.推定売上額) || 0).toLocaleString()}`;

    // 対応方針表示
    const policy = allPolicies.find(p => p.クライアントID === selectedClientId);
    if (policy) {
      policyPanel.style.display = 'block';
      container.querySelector('#policy-name').textContent = policy.対応方針名 || '-';
      const priorityText = { 1: '高', 2: '中', 3: '低' }[policy.優先度] || '-';
      container.querySelector('#policy-priority').textContent = priorityText;
      container.querySelector('#policy-frequency').textContent = policy.対応頻度 || '-';
      container.querySelector('#policy-content').textContent = policy.対応方針説明 || '-';
    } else {
      policyPanel.style.display = 'none';
    }

    // 対応履歴表示
    const histories = allHistories.filter(h => h.クライアントID === selectedClientId).slice(-5).reverse();
    historyPanel.style.display = 'block';
    container.querySelector('#history-list').innerHTML = histories.map(h => `
      <div style="padding: 6px; border-bottom: 1px solid rgba(255,255,255,0.08); line-height: 1.4;">
        <div style="font-weight: 600; color: var(--text); margin-bottom: 2px;">${h.対応種別 || '-'}</div>
        <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">${h.対応日時 ? h.対応日時.slice(0, 10) : '-'}</div>
        <div style="font-size: 11px; color: var(--text); margin-bottom: 2px;">${h.対応内容 || '-'}</div>
        <div style="font-size: 10px; color: var(--text-muted);">成果: ${h.成果 || '-'}</div>
      </div>
    `).join('');

    // 受注・案件表示
    const deals = allDeals.filter(d => d.クライアントID === selectedClientId).slice(-5).reverse();
    const projects = allProjects.filter(p => p.クライアントID === selectedClientId).slice(-5).reverse();
    const combined = [...deals.map(d => ({ ...d, type: '受注', date: d.受注日, amount: d.税込金額 })), 
                      ...projects.map(p => ({ ...p, type: '案件', date: p.予想受注日, amount: p.予想金額 }))].sort((a, b) => (b.date || '').localeCompare(a.date || '')).slice(0, 5);

    dealsPanel.style.display = 'block';
    container.querySelector('#deals-list').innerHTML = combined.map(item => `
      <div style="padding: 6px; border-bottom: 1px solid rgba(255,255,255,0.08); line-height: 1.4;">
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 2px;">
          <span style="font-weight: 600; color: var(--text);">${item.type === '受注' ? item.商品サービス名 : item.案件名 || '-'}</span>
          <span style="font-size: 10px; padding: 2px 6px; border-radius: 3px; background: rgba(255,165,0,0.15); color: #ffa500;">¥${(parseInt(item.amount) || 0).toLocaleString()}</span>
        </div>
        <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">${item.type === '受注' ? item.ステータス : item.ステータス || '-'}</div>
        <div style="font-size: 10px; color: var(--text-muted);">${item.date ? item.date.slice(0, 10) : '-'}</div>
      </div>
    `).join('');
  }

  // ===== 6. イベントリスナー登録 =====
  container.querySelector('#input-client-search').addEventListener('input', e => {
    renderClientList(e.target.value);
  });

  container.querySelector('#btn-new-client').addEventListener('click', () => {
    window.showScreen('scr-1781408824557'); // クライアント詳細情報画面
  });

  container.querySelector('#btn-edit-client').addEventListener('click', () => {
    if (selectedClientId) window.showScreen('scr-1781408824557');
  });

  container.querySelector('#btn-view-detail').addEventListener('click', () => {
    if (selectedClientId) window.showScreen('scr-1781408824557');
  });

  container.querySelector('#btn-edit-policy').addEventListener('click', () => {
    if (selectedClientId) window.showScreen('scr-1781408878914');
  });

  container.querySelector('#btn-new-history').addEventListener('click', () => {
    if (selectedClientId) window.showScreen('scr-1781408865891');
  });

  container.querySelector('#btn-new-deal').addEventListener('click', () => {
    if (selectedClientId) window.showScreen('scr-1781408904580');
  });

  // ===== 7. 初期化実行 =====
  loadAllData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const clientTableIdx = 0;      // クライアント
  const interactionTableIdx = 1; // 対応履歴
  const policyTableIdx = 2;      // 対応方針

  // 要素取得
  const clientListEl = container.querySelector("#client-list");
  const historyTimelineEl = container.querySelector("#history-timeline");
  const policyPanelEl = container.querySelector("#policy-panel");
  const clientDetailPanelEl = container.querySelector("#client-detail-panel");
  const selectedClientIdInput = container.querySelector("#selected-client-id");
  const selectedInteractionIdInput = container.querySelector("#selected-interaction-id");

  const interactionDatetimeInput = container.querySelector("#interaction-datetime");
  const interactionUserSelect = container.querySelector("#interaction-user");
  const interactionTypeSelect = container.querySelector("#interaction-type");
  const interactionResultSelect = container.querySelector("#interaction-result");
  const interactionContentTextarea = container.querySelector("#interaction-content");
  const btnSaveInteraction = container.querySelector("#btn-save-interaction");
  const btnCancelInteraction = container.querySelector("#btn-cancel-interaction");

  const clientSearchInput = container.querySelector("#client-search-input");

  // ===== 1. クライアント一覧を描画 =====
  function renderClientList(clients) {
    clientListEl.innerHTML = clients.map(client => `
      <div 
        class="client-item" 
        data-id="${client.id}" 
        style="padding: 8px; background: rgba(255,255,255,0.04); border-radius: 3px; cursor: pointer; border: 1px solid transparent; transition: all 0.2s;"
      >
        <div style="font-size: 12px; font-weight: 500; color: var(--text);">${client.クライアント名 || "（名前なし）"}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${client.業種 || "業種未設定"}</div>
      </div>
    `).join("");
  }

  // ===== 2. 対応履歴タイムラインを描画 =====
  function renderHistoryTimeline(interactions) {
    if (!interactions || interactions.length === 0) {
      historyTimelineEl.innerHTML = `
        <div style="color: var(--text-muted); font-size: 12px; text-align: center; padding: 20px;">
          対応履歴がありません
        </div>
      `;
      return;
    }

    // 日時でソート（新しい順）
    const sorted = [...interactions].sort((a, b) => {
      const dateA = new Date(a.対応日時 || 0);
      const dateB = new Date(b.対応日時 || 0);
      return dateB - dateA;
    });

    historyTimelineEl.innerHTML = sorted.map((interaction, idx) => {
      const date = new Date(interaction.対応日時);
      const dateStr = date.toLocaleString("ja-JP", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" });
      const typeLabel = {
        "phone": "📞 電話",
        "email": "📧 メール",
        "visit": "🚗 訪問",
        "meeting": "💼 商談",
        "proposal": "📄 提案"
      }[interaction.対応種別] || interaction.対応種別;

      const resultLabel = {
        "completed": "✓ 完了",
        "pending": "⏸ 保留",
        "in-progress": "⏳ 進行中",
        "order": "🎉 受注",
        "quote": "📋 見積提出",
        "material": "📦 資料送付"
      }[interaction.対応結果] || interaction.対応結果;

      return `
        <div 
          class="timeline-item" 
          data-id="${interaction.id}"
          style="padding: 10px; background: rgba(255,255,255,0.02); border-left: 3px solid var(--primary); border-radius: 2px; position: relative;"
        >
          <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 6px;">
            <div style="font-size: 11px; color: var(--text-muted);">${dateStr}</div>
            <div style="font-size: 10px; color: #d0e4ff; background: rgba(255,165,0,0.2); padding: 2px 6px; border-radius: 2px;">${typeLabel}</div>
          </div>
          <div style="font-size: 11px; color: var(--text); margin-bottom: 4px; word-break: break-word;">
            ${(interaction.対応内容 || "").substring(0, 100)}${(interaction.対応内容 || "").length > 100 ? "..." : ""}
          </div>
          <div style="font-size: 10px; color: #a0d468; margin-bottom: 6px;">${resultLabel}</div>
          <div style="display: flex; gap: 4px;">
            <button 
              class="edit-interaction-btn" 
              data-id="${interaction.id}"
              style="flex: 1; padding: 3px 6px; font-size: 10px; background: transparent; color: var(--text-muted); border: 1px solid rgba(255,255,255,0.18); border-radius: 2px; cursor: pointer; transition: all 0.2s;"
            >
              編集
            </button>
            <button 
              class="delete-interaction-btn" 
              data-id="${interaction.id}"
              style="flex: 1; padding: 3px 6px; font-size: 10px; background: transparent; color: #ff6b6b; border: 1px solid rgba(255,107,107,0.3); border-radius: 2px; cursor: pointer; transition: all 0.2s;"
            >
              削除
            </button>
          </div>
        </div>
      `;
    }).join("");
  }

  // ===== 3. 対応方針パネルを描画 =====
  function renderPolicyPanel(clientId) {
    if (!clientId) {
      policyPanelEl.innerHTML = "クライアントを選択してください";
      return;
    }

    const policies = (tables[policyTableIdx]?.records || []).filter(p => p.クライアントID === clientId);
    if (policies.length === 0) {
      policyPanelEl.innerHTML = `<div style="color: var(--text-muted); font-size: 11px;">対応方針が設定されていません</div>`;
      return;
    }

    policyPanelEl.innerHTML = policies.map(policy => `
      <div style="margin-bottom: 10px; padding: 8px; background: rgba(255,165,0,0.08); border-left: 2px solid #ffa500; border-radius: 2px;">
        <div style="font-size: 11px; font-weight: 600; color: var(--text); margin-bottom: 3px;">${policy.方針名 || "（名前なし）"}</div>
        <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 3px; line-height: 1.4;">
          ${(policy.方針内容 || "").substring(0, 150)}${(policy.方針内容 || "").length > 150 ? "..." : ""}
        </div>
        <div style="font-size: 10px; color: #d0e4ff;">
          優先度: <strong>${["高", "中", "低"][policy.優先度 - 1] || "未設定"}</strong> | 
          頻度: ${policy.対応頻度 || "未設定"}
        </div>
      </div>
    `).join("");
  }

  // ===== 4. クライアント詳細パネルを描画 =====
  function renderClientDetailPanel(clientId) {
    if (!clientId) {
      clientDetailPanelEl.innerHTML = `<div style="padding: 8px; text-align: center; color: var(--text-muted); font-size: 12px;">クライアントを選択してください</div>`;
      return;
    }

    const client = (tables[clientTableIdx]?.records || []).find(c => c.id === clientId);
    if (!client) {
      clientDetailPanelEl.innerHTML = `<div style="color: var(--text-muted); font-size: 11px;">クライアント情報が見つかりません</div>`;
      return;
    }

    clientDetailPanelEl.innerHTML = `
      <div style="display: flex; flex-direction: column; gap: 6px; font-size: 11px;">
        <div>
          <div style="color: var(--text-muted); margin-bottom: 2px;">企業名</div>
          <div style="color: var(--text); font-weight: 500;">${client.クライアント名 || "—"}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); margin-bottom: 2px;">業種</div>
          <div style="color: var(--text);">${client.業種 || "—"}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); margin-bottom: 2px;">代表者</div>
          <div style="color: var(--text);">${client.代表者名 || "—"}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); margin-bottom: 2px;">メール</div>
          <div style="color: var(--text); word-break: break-all;">${client.メールアドレス || "—"}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); margin-bottom: 2px;">電話</div>
          <div style="color: var(--text);">${client.電話番号 || "—"}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); margin-bottom: 2px;">ステータス</div>
          <div style="color: var(--text); padding: 2px 6px; background: rgba(255,165,0,0.15); border-radius: 2px; display: inline-block;">
            ${client.ステータス || "—"}
          </div>
        </div>
      </div>
    `;
  }

  // ===== 5. 初期データ読み込み =====
  const initialClients = tables[clientTableIdx]?.records || [];
  renderClientList(initialClients);

  // ===== 6. クライアント検索 =====
  clientSearchInput.addEventListener("input", () => {
    const keyword = clientSearchInput.value.toLowerCase();
    const filtered = initialClients.filter(c => 
      (c.クライアント名 || "").toLowerCase().includes(keyword) ||
      (c.業種 || "").toLowerCase().includes(keyword)
    );
    renderClientList(filtered);
  });

  // ===== 7. クライアント選択 =====
  container.addEventListener("click", (e) => {
    const clientItem = e.target.closest(".client-item");
    if (clientItem) {
      const clientId = clientItem.dataset.id;
      selectedClientIdInput.value = clientId;

      // ハイライト
      container.querySelectorAll(".client-item").forEach(el => {
        el.style.background = el.dataset.id === clientId ? "rgba(255,165,0,0.2)" : "rgba(255,255,255,0.04)";
        el.style.borderColor = el.dataset.id === clientId ? "var(--primary)" : "transparent";
      });

      // 対応履歴を読み込んで表示
      const interactions = (tables[interactionTableIdx]?.records || []).filter(i => i.クライアントID === clientId);
      renderHistoryTimeline(interactions);

      // 対応方針を表示
      renderPolicyPanel(clientId);

      // クライアント詳細を表示
      renderClientDetailPanel(clientId);

      // フォームをクリア
      clearInteractionForm();
    }
  });

  // ===== 8. 対応記録フォーム: クリア =====
  function clearInteractionForm() {
    interactionDatetimeInput.value = new Date().toISOString().slice(0, 16);
    interactionUserSelect.value = "";
    interactionTypeSelect.value = "";
    interactionResultSelect.value = "";
    interactionContentTextarea.value = "";
    selectedInteractionIdInput.value = "";
  }

  btnCancelInteraction.addEventListener("click", clearInteractionForm);

  // ===== 9. 対応記録フォーム: 保存 =====
  btnSaveInteraction.addEventListener("click", async () => {
    const clientId = selectedClientIdInput.value;
    if (!clientId) {
      alert("クライアントを選択してください");
      return;
    }

    const datetime = interactionDatetimeInput.value;
    const userId = interactionUserSelect.value;
    const type = interactionTypeSelect.value;
    const result = interactionResultSelect.value;
    const content = interactionContentTextarea.value;

    if (!datetime || !userId || !type || !result || !content) {
      alert("すべての項目を入力してください");
      return;
    }

    const interactionId = selectedInteractionIdInput.value;
    const payload = {
      クライアントID: clientId,
      ユーザーID: userId,
      対応種別: type,
      対応日時: new Date(datetime).toISOString(),
      対応内容: content,
      対応結果: result,
      ステータス: "完了"
    };

    if (interactionId) {
      // 更新
      const updated = await window.aivicApi.update(interactionTableIdx, interactionId, payload);
      if (updated) {
        alert("対応履歴を更新しました");
        const interactions = (tables[interactionTableIdx]?.records || []).filter(i => i.クライアントID === clientId);
        renderHistoryTimeline(interactions);
        clearInteractionForm();
      }
    } else {
      // 新規保存
      const saved = await window.aivicApi.save(interactionTableIdx, payload);
      if (saved) {
        alert("対応履歴を追加しました");
        const interactions = (tables[interactionTableIdx]?.records || []).filter(i => i.クライアントID === clientId);
        renderHistoryTimeline(interactions);
        clearInteractionForm();
      }
    }
  });

  // ===== 10. 対応履歴: 編集 =====
  container.addEventListener("click", async (e) => {
    const editBtn = e.target.closest(".edit-interaction-btn");
    if (editBtn) {
      const interactionId = editBtn.dataset.id;
      const interaction = (tables[interactionTableIdx]?.records || []).find(i => i.id === interactionId);
      if (!interaction) return;

      selectedInteractionIdInput.value = interactionId;
      interactionDatetimeInput.value = new Date(interaction.対応日時).toISOString().slice(0, 16);
      interactionUserSelect.value = interaction.ユーザーID || "";
      interactionTypeSelect.value = interaction.対応種別 || "";
      interactionResultSelect.value = interaction.対応結果 || "";
      interactionContentTextarea.value = interaction.対応内容 || "";

      // スクロール
      container.querySelector("#btn-save-interaction").scrollIntoView({ behavior: "smooth", block: "nearest" });
    }
  });

  // ===== 11. 対応履歴: 削除 =====
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-interaction-btn");
    if (deleteBtn) {
      const interactionId = deleteBtn.dataset.id;
      if (!confirm("この対応履歴を削除しますか？")) return;

      const deleted = await window.aivicApi.delete(interactionTableIdx, interactionId);
      if (deleted) {
        alert("対応履歴を削除しました");
        const clientId = selectedClientIdInput.value;
        const interactions = (tables[interactionTableIdx]?.records || []).filter(i => i.クライアントID === clientId);
        renderHistoryTimeline(interactions);
      }
    }
  });

  // 初期フォーム設定
  clearInteractionForm();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const CONTACT_HISTORY_IDX = 0;
  const CLIENT_IDX = 1;
  const PROJECT_IDX = 2;
  const ORDER_IDX = 3;
  const POLICY_IDX = 4;

  // フォーム要素の取得
  const clientSelect = container.querySelector('#client-select');
  const projectSelect = container.querySelector('#project-select');
  const contactDatetime = container.querySelector('#contact-datetime');
  const contactMethod = container.querySelector('#contact-method');
  const contactContent = container.querySelector('#contact-content');
  const policySelect = container.querySelector('#policy-select');
  const nextContactDate = container.querySelector('#next-contact-date');
  const fileUpload = container.querySelector('#file-upload');
  const fileList = container.querySelector('#file-list');
  const btnSave = container.querySelector('#btn-save');
  const btnCancel = container.querySelector('#btn-cancel');

  // プレビュー要素
  const clientPreview = container.querySelector('#client-preview');
  const projectPreview = container.querySelector('#project-preview');
  const orderPreview = container.querySelector('#order-preview');
  const policyPreview = container.querySelector('#policy-preview');
  const historyPreview = container.querySelector('#history-preview');
  const noPreview = container.querySelector('#no-preview');

  // 初期データの参照
  const clients = tables[CLIENT_IDX]?.records || [];
  const projects = tables[PROJECT_IDX]?.records || [];
  const orders = tables[ORDER_IDX]?.records || [];
  const policies = tables[POLICY_IDX]?.records || [];
  const histories = tables[CONTACT_HISTORY_IDX]?.records || [];

  // 現在の日時をデフォルト値に設定
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  const hours = String(now.getHours()).padStart(2, '0');
  const minutes = String(now.getMinutes()).padStart(2, '0');
  contactDatetime.value = `${year}-${month}-${day}T${hours}:${minutes}`;

  // ファイルアップロード管理
  const uploadedFiles = [];
  fileUpload.addEventListener('change', (e) => {
    uploadedFiles.length = 0;
    fileList.innerHTML = '';
    Array.from(e.target.files).forEach(file => {
      uploadedFiles.push(file);
      const fileItem = document.createElement('div');
      fileItem.style.cssText = 'font-size: 12px; color: var(--text-muted); margin-top: 4px; padding: 4px 6px; background: rgba(0,0,0,0.15); border-radius: 3px;';
      fileItem.textContent = `📎 ${file.name}`;
      fileList.appendChild(fileItem);
    });
  });

  // プレビュー更新関数
  function updatePreview() {
    const selectedClientId = clientSelect.value;
    const selectedProjectId = projectSelect.value;

    // プレビューをリセット
    clientPreview.style.display = 'none';
    projectPreview.style.display = 'none';
    orderPreview.style.display = 'none';
    policyPreview.style.display = 'none';
    historyPreview.style.display = 'none';
    noPreview.style.display = 'block';

    if (!selectedClientId) return;

    // クライアント情報表示
    const client = clients.find(c => c.id === selectedClientId || c.クライアント名 === selectedClientId);
    if (client) {
      container.querySelector('#preview-client-name').textContent = client.クライアント名 || client.name || '-';
      container.querySelector('#preview-client-industry').textContent = client.業種 || client.industry || '-';
      container.querySelector('#preview-client-rep').textContent = client.代表者名 || client.representative || '-';
      container.querySelector('#preview-client-phone').textContent = client.電話番号 || client.phone || '-';
      container.querySelector('#preview-client-status').textContent = client.ステータス || client.status || '-';
      clientPreview.style.display = 'block';
      noPreview.style.display = 'none';
    }

    if (!selectedProjectId) return;

    // 案件情報表示
    const project = projects.find(p => p.id === selectedProjectId || p.案件名 === selectedProjectId);
    if (project) {
      container.querySelector('#preview-project-name').textContent = project.案件名 || project.name || '-';
      container.querySelector('#preview-project-status').textContent = project.ステータス || project.status || '-';
      container.querySelector('#preview-project-amount').textContent = project.予想金額 ? `¥${Number(project.予想金額).toLocaleString()}` : '-';
      container.querySelector('#preview-project-probability').textContent = project.成約確度 ? `${project.成約確度}%` : '-';
      container.querySelector('#preview-project-date').textContent = project.予想受注日 || '-';
      projectPreview.style.display = 'block';
    }

    // 受注情報表示
    const order = orders.find(o => o.クライアントID === selectedClientId || o.clientId === selectedClientId);
    if (order) {
      container.querySelector('#preview-order-date').textContent = order.受注日 || order.orderDate || '-';
      container.querySelector('#preview-order-amount').textContent = order.受注金額 ? `¥${Number(order.受注金額).toLocaleString()}` : '-';
      container.querySelector('#preview-order-product').textContent = order['商品・サービス名'] || order.productName || '-';
      container.querySelector('#preview-order-status').textContent = order.ステータス || order.status || '-';
      orderPreview.style.display = 'block';
    }

    // 対応方針表示
    const policy = policies.find(p => p.クライアントID === selectedClientId || p.clientId === selectedClientId);
    if (policy) {
      container.querySelector('#preview-policy-name').textContent = policy.対応方針名 || policy.policyName || '-';
      const priorityMap = { 1: '高', 2: '中', 3: '低' };
      container.querySelector('#preview-policy-priority').textContent = priorityMap[policy.優先度] || '-';
      container.querySelector('#preview-policy-frequency').textContent = policy.対応頻度 || policy.frequency || '-';
      container.querySelector('#preview-policy-next-date').textContent = policy.次回対応予定日 || policy.nextDate || '-';
      policyPreview.style.display = 'block';
    }

    // 過去対応履歴表示
    const clientHistories = histories.filter(h => h.クライアントID === selectedClientId || h.clientId === selectedClientId).slice(0, 3);
    if (clientHistories.length > 0) {
      const historyHtml = clientHistories.map(h => {
        const date = h.対応日時 || h.contactDate || '-';
        const method = h.対応種別 || h.method || '-';
        const content = (h.対応内容 || h.content || '-').substring(0, 30) + '...';
        return `<div style="padding: 6px 0; border-bottom: 1px solid rgba(255,255,255,0.05);">
          <div style="font-size: 11px; color: var(--text-muted);">${date}</div>
          <div style="font-size: 12px; color: var(--text);">${method} - ${content}</div>
        </div>`;
      }).join('');
      container.querySelector('#history-list').innerHTML = historyHtml;
      historyPreview.style.display = 'block';
    }
  }

  // イベントリスナー
  clientSelect.addEventListener('change', updatePreview);
  projectSelect.addEventListener('change', updatePreview);

  // 登録ボタン
  btnSave.addEventListener('click', async () => {
    // バリデーション
    if (!clientSelect.value) {
      alert('クライアントを選択してください');
      return;
    }
    if (!projectSelect.value) {
      alert('案件を選択してください');
      return;
    }
    if (!contactDatetime.value) {
      alert('対応日時を入力してください');
      return;
    }
    if (!contactMethod.value) {
      alert('対応方法を選択してください');
      return;
    }
    if (!contactContent.value.trim()) {
      alert('対応内容を入力してください');
      return;
    }

    // 保存データ構築
    const saveData = {
      クライアントID: clientSelect.value,
      案件ID: projectSelect.value,
      ユーザーID: 'current-user-id',
      対応種別: contactMethod.value,
      対応日時: contactDatetime.value,
      対応内容: contactContent.value,
      次回対応予定日: nextContactDate.value || null,
      ステータス: '完了',
      成果: policySelect.value || null,
    };

    // API保存
    const result = await window.aivicApi.save(CONTACT_HISTORY_IDX, saveData);
    if (result) {
      alert('対応履歴を登録しました');
      // フォームリセット
      clientSelect.value = '';
      projectSelect.value = '';
      contactContent.value = '';
      policySelect.value = '';
      nextContactDate.value = '';
      fileUpload.value = '';
      fileList.innerHTML = '';
      uploadedFiles.length = 0;
      updatePreview();
      // 初期日時を再設定
      const now = new Date();
      const year = now.getFullYear();
      const month = String(now.getMonth() + 1).padStart(2, '0');
      const day = String(now.getDate()).padStart(2, '0');
      const hours = String(now.getHours()).padStart(2, '0');
      const minutes = String(now.getMinutes()).padStart(2, '0');
      contactDatetime.value = `${year}-${month}-${day}T${hours}:${minutes}`;
    }
  });

  // キャンセルボタン
  btnCancel.addEventListener('click', () => {
    if (confirm('入力内容を破棄してもよろしいですか？')) {
      window.showScreen('scr-1781408840123');
    }
  });
}

function(container, apiUrl, tables) {
  const form = container.querySelector("#project-form");
  const successMsg = container.querySelector("#success-message");
  const errorMsg = container.querySelector("#error-message");
  const fileUpload = container.querySelector("#file-upload");
  const fileName = container.querySelector("#file-name");

  // ファイル選択時のファイル名表示
  fileUpload.addEventListener("change", (e) => {
    if (e.target.files.length > 0) {
      fileName.textContent = `選択: ${e.target.files[0].name}`;
    } else {
      fileName.textContent = "";
    }
  });

  // 対応履歴参照ボタン
  container.querySelector("#btn-history").addEventListener("click", () => {
    const clientId = container.querySelector("#client-select").value;
    if (!clientId) {
      errorMsg.textContent = "クライアントを選択してください。";
      errorMsg.style.display = "block";
      setTimeout(() => { errorMsg.style.display = "none"; }, 3000);
      return;
    }
    // 対応履歴・対応方針管理画面へ遷移
    window.showScreen("scr-1781408840123");
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    if (confirm("入力内容を破棄してもよろしいですか？")) {
      form.reset();
      fileName.textContent = "";
      successMsg.style.display = "none";
      errorMsg.style.display = "none";
      // クライアント統合ダッシュボードへ遷移
      window.showScreen("scr-1781408811435");
    }
  });

  // フォーム送信（登録）
  form.addEventListener("submit", async (e) => {
    e.preventDefault();
    successMsg.style.display = "none";
    errorMsg.style.display = "none";

    // 必須項目チェック
    const projectName = container.querySelector("#project-name").value.trim();
    const clientId = container.querySelector("#client-select").value;
    const status = container.querySelector("#status-select").value;
    const projectType = container.querySelector("#type-select").value;
    const assigneeId = container.querySelector("#assignee-select").value;

    if (!projectName) {
      errorMsg.textContent = "案件名を入力してください。";
      errorMsg.style.display = "block";
      return;
    }
    if (!clientId) {
      errorMsg.textContent = "クライアントを選択してください。";
      errorMsg.style.display = "block";
      return;
    }
    if (!status) {
      errorMsg.textContent = "ステータスを選択してください。";
      errorMsg.style.display = "block";
      return;
    }
    if (!projectType) {
      errorMsg.textContent = "案件種別を選択してください。";
      errorMsg.style.display = "block";
      return;
    }
    if (!assigneeId) {
      errorMsg.textContent = "担当者を選択してください。";
      errorMsg.style.display = "block";
      return;
    }

    // フォームデータ収集
    const formData = {
      projectName,
      clientId,
      status,
      projectType,
      estimatedAmount: parseInt(container.querySelector("#estimated-amount").value) || 0,
      startDate: container.querySelector("#start-date").value || null,
      endDate: container.querySelector("#end-date").value || null,
      assigneeId,
      policyAggressive: container.querySelector("#policy-aggressive").checked,
      policyFollowup: container.querySelector("#policy-followup").checked,
      policyConservative: container.querySelector("#policy-conservative").checked,
      description: container.querySelector("#description").value.trim(),
      attachment: fileUpload.files.length > 0 ? fileUpload.files[0].name : null
    };

    // API保存（tableIndex=0 が案件テーブル）
    const saved = await window.aivicApi.save(0, formData);
    if (!saved) {
      errorMsg.textContent = "登録に失敗しました。もう一度お試しください。";
      errorMsg.style.display = "block";
      return;
    }

    // 成功メッセージ表示
    successMsg.style.display = "block";
    form.reset();
    fileName.textContent = "";

    // 2秒後に一覧画面へ遷移
    setTimeout(() => {
      window.showScreen("scr-1781408853048");
    }, 2000);
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 受注テーブルは tables[0]
  const orderTableIndex = 0;
  const clientTableIndex = 1;
  const contactHistoryTableIndex = 2;
  const projectTableIndex = 3;
  const userTableIndex = 4;

  let allOrders = [];
  let selectedOrder = null;

  // ===== 1. 再描画関数 =====
  function renderRows(rows) {
    const tbody = container.querySelector("#records-tbody");
    tbody.innerHTML = rows.map(r => {
      const orderDate = r.受注日 ? new Date(r.受注日).toLocaleDateString('ja-JP') : '-';
      const amount = r.受注金額 ? r.受注金額.toLocaleString('ja-JP') : '0';
      const statusClass = getStatusClass(r.ステータス);
      return `
        <tr data-id="${r.受注ID || ''}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.15s;" onmouseover="this.style.background='rgba(212,165,116,0.08)'" onmouseout="this.style.background=''">
          <td style="padding: 0.5rem 0.75rem; color: var(--text);">${r.受注ID || '-'}</td>
          <td style="padding: 0.5rem 0.75rem; color: var(--text);">${r.クライアント名 || '-'}</td>
          <td style="padding: 0.5rem 0.75rem; color: var(--text);">${r.案件名 || '-'}</td>
          <td style="padding: 0.5rem 0.75rem; color: var(--text);">${orderDate}</td>
          <td style="padding: 0.5rem 0.75rem; color: var(--text); text-align: right;">¥${amount}</td>
          <td style="padding: 0.5rem 0.75rem; text-align: center;">
            <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; font-weight: 500; ${statusClass}">
              ${r.ステータス || '-'}
            </span>
          </td>
          <td style="padding: 0.5rem 0.75rem; color: var(--text);">${r.営業担当者名 || '-'}</td>
        </tr>
      `;
    }).join("");
    container.querySelector("#record-count").textContent = rows.length;
  }

  function getStatusClass(status) {
    const statusMap = {
      '受注確定': 'background: rgba(212, 165, 116, 0.2); color: #d4a574;',
      '納品待ち': 'background: rgba(255, 152, 0, 0.2); color: #ff9800;',
      '完了': 'background: rgba(76, 175, 80, 0.2); color: #4caf50;',
      'キャンセル': 'background: rgba(244, 67, 54, 0.2); color: #f44336;'
    };
    return statusMap[status] || 'background: rgba(158, 158, 158, 0.2); color: #9e9e9e;';
  }

  // ===== 2. 初期データ読み込み =====
  async function loadInitialData() {
    const orders = await window.aivicApi.list(orderTableIndex);
    if (orders) {
      allOrders = orders;
      renderRows(allOrders);
    }

    // 営業担当者セレクトを動的に生成
    const users = await window.aivicApi.list(userTableIndex);
    if (users) {
      const userSelect = container.querySelector("#filter-sales-user");
      users.forEach(u => {
        const opt = document.createElement("option");
        opt.value = u.ユーザーID || '';
        opt.textContent = u.氏名 || u.ログインID || '';
        userSelect.appendChild(opt);
      });
    }
  }

  // ===== 3. 検索ボタン =====
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const clientName = container.querySelector("#filter-client-name").value.trim();
    const dateFrom = container.querySelector("#filter-order-date-from").value;
    const dateTo = container.querySelector("#filter-order-date-to").value;
    const status = container.querySelector("#filter-status").value;
    const projectName = container.querySelector("#filter-project-name").value.trim();
    const salesUserId = container.querySelector("#filter-sales-user").value;
    const amountMin = parseInt(container.querySelector("#filter-amount-min").value) || 0;
    const amountMax = parseInt(container.querySelector("#filter-amount-max").value) || Infinity;

    let filtered = allOrders.filter(r => {
      const matchClient = !clientName || (r.クライアント名 && r.クライアント名.includes(clientName));
      const matchStatus = !status || r.ステータス === status;
      const matchProject = !projectName || (r.案件名 && r.案件名.includes(projectName));
      const matchUser = !salesUserId || r.営業担当者ID === salesUserId;
      const matchAmount = (r.受注金額 || 0) >= amountMin && (r.受注金額 || 0) <= amountMax;

      let matchDate = true;
      if (dateFrom || dateTo) {
        const orderDate = r.受注日 ? new Date(r.受注日) : null;
        if (dateFrom && orderDate < new Date(dateFrom)) matchDate = false;
        if (dateTo && orderDate > new Date(dateTo)) matchDate = false;
      }

      return matchClient && matchStatus && matchProject && matchUser && matchAmount && matchDate;
    });

    renderRows(filtered);
  });

  // ===== 4. リセットボタン =====
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-client-name").value = "";
    container.querySelector("#filter-order-date-from").value = "";
    container.querySelector("#filter-order-date-to").value = "";
    container.querySelector("#filter-status").value = "";
    container.querySelector("#filter-project-name").value = "";
    container.querySelector("#filter-sales-user").value = "";
    container.querySelector("#filter-amount-min").value = "";
    container.querySelector("#filter-amount-max").value = "";
    renderRows(allOrders);
  });

  // ===== 5. 行クリックでクライアント情報パネル更新 =====
  container.addEventListener("click", async (e) => {
    const row = e.target.closest("tr[data-id]");
    if (row) {
      const orderId = row.dataset.id;
      selectedOrder = allOrders.find(o => o.受注ID === orderId);

      if (selectedOrder) {
        // クライアント情報を取得
        const clients = await window.aivicApi.list(clientTableIndex);
        const client = clients ? clients.find(c => c.クライアントID === selectedOrder.クライアントID) : null;

        const panelDiv = container.querySelector("#client-panel");
        if (client) {
          panelDiv.innerHTML = `
            <div>
              <div style="color: var(--text-muted); font-size: 0.75rem;">クライアント名</div>
              <div style="color: var(--text); font-weight: 500;">${client.クライアント名 || '-'}</div>
            </div>
            <div>
              <div style="color: var(--text-muted); font-size: 0.75rem;">業種</div>
              <div style="color: var(--text);">${client.業種 || '-'}</div>
            </div>
            <div>
              <div style="color: var(--text-muted); font-size: 0.75rem;">代表者名</div>
              <div style="color: var(--text);">${client.代表者名 || '-'}</div>
            </div>
            <div>
              <div style="color: var(--text-muted); font-size: 0.75rem;">メールアドレス</div>
              <div style="color: var(--text); word-break: break-all;">${client.メールアドレス || '-'}</div>
            </div>
            <div>
              <div style="color: var(--text-muted); font-size: 0.75rem;">電話番号</div>
              <div style="color: var(--text);">${client.電話番号 || '-'}</div>
            </div>
            <div>
              <div style="color: var(--text-muted); font-size: 0.75rem;">ステータス</div>
              <div style="color: var(--text);">${client.ステータス || '-'}</div>
            </div>
          `;
        } else {
          panelDiv.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 1rem 0;">クライアント情報が見つかりません</div>';
        }

        // 対応履歴を取得
        const histories = await window.aivicApi.list(contactHistoryTableIndex);
        const clientHistories = histories ? histories.filter(h => h.クライアントID === selectedOrder.クライアントID).sort((a, b) => new Date(b.対応日時) - new Date(a.対応日時)).slice(0, 3) : [];

        const historyDiv = container.querySelector("#contact-history-snippet");
        if (clientHistories.length > 0) {
          historyDiv.innerHTML = clientHistories.map(h => {
            const date = h.対応日時 ? new Date(h.対応日時).toLocaleDateString('ja-JP') : '-';
            return `
              <div style="padding: 0.5rem 0; border-bottom: 1px solid rgba(255,255,255,0.08);">
                <div style="color: var(--text); font-weight: 500; font-size: 0.75rem;">${h.対応種別 || '-'}</div>
                <div style="color: var(--text-muted); font-size: 0.7rem;">${date}</div>
                <div style="color: var(--text); font-size: 0.7rem; margin-top: 0.25rem; line-height: 1.3;">${(h.対応内容 || '').substring(0, 60)}${(h.対応内容 || '').length > 60 ? '...' : ''}</div>
              </div>
            `;
          }).join("");
        } else {
          historyDiv.innerHTML = '<div style="text-align: center; padding: 0.5rem 0; color: var(--text-muted);">対応履歴なし</div>';
        }

        // 詳細表示ボタンを有効化
        container.querySelector("#btn-view-detail").disabled = false;
      }
    }
  });

  // ===== 6. 詳細表示ボタン =====
  container.querySelector("#btn-view-detail").addEventListener("click", () => {
    if (selectedOrder && selectedOrder.クライアントID) {
      window.showScreen("scr-1781408824557", { clientId: selectedOrder.クライアントID });
    }
  });

  // ===== 7. CSVエクスポート =====
  container.querySelector("#btn-export-csv").addEventListener("click", async () => {
    const orders = await window.aivicApi.list(orderTableIndex);
    if (!orders || orders.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["受注ID", "クライアント名", "案件名", "受注日", "受注金額", "税額", "税込金額", "ステータス", "商品・サービス名", "納期", "納品日", "備考"];
    const rows = orders.map(r => [
      r.受注ID || "",
      r.クライアント名 || "",
      r.案件名 || "",
      r.受注日 ? new Date(r.受注日).toLocaleDateString('ja-JP') : "",
      r.受注金額 || "",
      r.税額 || "",
      r.税込金額 || "",
      r.ステータス || "",
      r.商品・サービス名 || "",
      r.納期 ? new Date(r.納期).toLocaleDateString('ja-JP') : "",
      r.納品日 ? new Date(r.納品日).toLocaleDateString('ja-JP') : "",
      r.備考 || ""
    ]);

    const csv = [
      "\uFEFF" + headers.map(h => `"${h}"`).join(","),
      ...rows.map(r => r.map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `受注履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#result-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const detailContent = container.querySelector("#detail-content");
  const detailTitle = container.querySelector("#detail-title");

  let allRows = [];
  let selectedClientId = null;

  // 1. テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const lastContact = r.最終接触日 ? new Date(r.最終接触日).toLocaleDateString('ja-JP') : '—';
      return `
        <tr 
          data-id="${r.id}" 
          style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;"
          onmouseover="this.style.background='rgba(212,175,55,0.04)'"
          onmouseout="this.style.background='transparent'"
        >
          <td style="padding: 0.75rem; color: var(--text);">${r.クライアント名 || '—'}</td>
          <td style="padding: 0.75rem; color: var(--text);">${r.業種 || '—'}</td>
          <td style="padding: 0.75rem; color: var(--text);">${r.住所 ? r.住所.split('都|道|府|県')[0] + (r.住所.match(/都|道|府|県/) ? r.住所.match(/都|道|府|県/)[0] : '') : '—'}</td>
          <td style="padding: 0.75rem; color: var(--text-muted); font-size: 0.8rem;">${lastContact}</td>
          <td style="padding: 0.75rem;">
            <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; font-weight: 600; background: ${r.ステータス === '既存顧客' ? 'rgba(212,175,55,0.2)' : r.ステータス === '見込み客' ? 'rgba(100,150,200,0.2)' : 'rgba(150,150,150,0.2)'}; color: var(--text);">
              ${r.ステータス || '—'}
            </span>
          </td>
          <td style="padding: 0.75rem; text-align: center;">
            <button class="view-detail-btn" data-id="${r.id}" style="background: transparent; border: none; color: var(--primary); cursor: pointer; font-weight: 600; font-size: 0.875rem;">表示</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ描画
  if (tables[0] && tables[0].records) {
    allRows = tables[0].records;
    renderRows(allRows);
  }

  // 3. 詳細パネル表示関数
  function showDetail(clientId) {
    const client = allRows.find(r => r.id === clientId);
    if (!client) return;

    selectedClientId = clientId;
    detailTitle.textContent = client.クライアント名 || 'クライアント詳細';

    detailContent.innerHTML = `
      <div style="display: flex; flex-direction: column; gap: 0.75rem;">
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">クライアント名</div>
          <div style="color: var(--text); font-weight: 500;">${client.クライアント名 || '—'}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">業種</div>
          <div style="color: var(--text);">${client.業種 || '—'}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">代表者名</div>
          <div style="color: var(--text);">${client.代表者名 || '—'}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">メールアドレス</div>
          <div style="color: var(--text); word-break: break-all;">${client.メールアドレス || '—'}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">電話番号</div>
          <div style="color: var(--text);">${client.電話番号 || '—'}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">ステータス</div>
          <div style="color: var(--text);">${client.ステータス || '—'}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">推定売上額</div>
          <div style="color: var(--text); font-weight: 600;">¥${client.推定売上額 ? client.推定売上額.toLocaleString() : '—'}</div>
        </div>
        <div>
          <div style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600; margin-bottom: 0.25rem;">最終接触日</div>
          <div style="color: var(--text);">${client.最終接触日 ? new Date(client.最終接触日).toLocaleDateString('ja-JP') : '—'}</div>
        </div>
      </div>
    `;

    detailPanel.style.display = 'block';
  }

  // 4. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const clientName = container.querySelector("#input-client-name").value.toLowerCase();
    const clientId = container.querySelector("#input-client-id").value.toLowerCase();
    const industry = container.querySelector("#select-industry").value;
    const region = container.querySelector("#select-region").value;
    const projectStatus = container.querySelector("#select-project-status").value;
    const policy = container.querySelector("#select-policy").value;
    const orderStatus = container.querySelector("#select-order-status").value;
    const dateFrom = container.querySelector("#input-date-from").value;

    const filtered = allRows.filter(r => {
      const matchName = !clientName || (r.クライアント名 || '').toLowerCase().includes(clientName);
      const matchId = !clientId || (r.id || '').toLowerCase().includes(clientId);
      const matchIndustry = !industry || r.業種 === industry;
      const matchRegion = !region || (r.住所 || '').includes(region);
      const matchOrderStatus = !orderStatus || r.契約状況 === orderStatus;
      const matchDate = !dateFrom || (r.最終接触日 && new Date(r.最終接触日) >= new Date(dateFrom));

      return matchName && matchId && matchIndustry && matchRegion && matchOrderStatus && matchDate;
    });

    renderRows(filtered);
  });

  // 5. リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#input-client-name").value = '';
    container.querySelector("#input-client-id").value = '';
    container.querySelector("#select-industry").value = '';
    container.querySelector("#select-region").value = '';
    container.querySelector("#select-project-status").value = '';
    container.querySelector("#select-policy").value = '';
    container.querySelector("#select-order-status").value = '';
    container.querySelector("#input-date-from").value = '';
    renderRows(allRows);
  });

  // 6. CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", () => {
    if (allRows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ['クライアント名', '業種', '代表者名', 'メールアドレス', '電話番号', 'ステータス', '推定売上額', '最終接触日'];
    const rows = allRows.map(r => [
      r.クライアント名 || '',
      r.業種 || '',
      r.代表者名 || '',
      r.メールアドレス || '',
      r.電話番号 || '',
      r.ステータス || '',
      r.推定売上額 || '',
      r.最終接触日 ? new Date(r.最終接触日).toLocaleDateString('ja-JP') : ''
    ]);

    const csv = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `clients_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 7. 詳細表示ボタン（イベントデリゲーション）
  container.addEventListener("click", e => {
    const viewBtn = e.target.closest(".view-detail-btn");
    if (viewBtn) {
      showDetail(viewBtn.dataset.id);
    }

    const closeBtn = e.target.closest("#btn-close-detail");
    if (closeBtn) {
      detailPanel.style.display = 'none';
    }

    const viewDetailBtn = e.target.closest("#btn-view-detail");
    if (viewDetailBtn && selectedClientId) {
      window.showScreen("scr-1781408824557");
    }

    const editBtn = e.target.closest("#btn-edit-client");
    if (editBtn && selectedClientId) {
      window.showScreen("scr-1781408824557");
    }
  });

  // 8. 行クリックで詳細表示
  container.addEventListener("click", e => {
    const row = e.target.closest("tr[data-id]");
    if (row && !e.target.closest("button")) {
      showDetail(row.dataset.id);
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（tables 配列の順序に依存）
  const TABLE_CLIENT = 0;
  const TABLE_HISTORY = 1;
  const TABLE_PROJECT = 2;
  const TABLE_ORDER = 3;
  const TABLE_POLICY = 4;

  let selectedClientId = null;
  let allClients = [];
  let allHistories = [];
  let allProjects = [];
  let allOrders = [];

  // ===== 1. 再描画関数 =====
  function renderClients(clients) {
    const tbody = container.querySelector("#client-tbody");
    tbody.innerHTML = clients.map(c => `
      <tr data-id="${c.id}" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.05);" class="client-row">
        <td style="padding: 8px; font-size: 13px;">${c.クライアント名 || "—"}</td>
        <td style="padding: 8px; font-size: 13px; color: var(--text-muted);">${c.業種 || "—"}</td>
        <td style="padding: 8px; font-size: 12px;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${getStatusColor(c.ステータス)}; color: #fff; font-size: 11px;">
            ${c.ステータス || "—"}
          </span>
        </td>
      </tr>
    `).join("");
  }

  function getStatusColor(status) {
    const colors = {
      "見込み客": "rgba(212, 165, 116, 0.6)",
      "既存顧客": "rgba(196, 30, 58, 0.6)",
      "休止中": "rgba(255,255,255,0.2)"
    };
    return colors[status] || "rgba(255,255,255,0.2)";
  }

  function renderDetailPanel(client) {
    if (!client) {
      container.querySelector("#detail-panel").style.display = "none";
      container.querySelector("#no-selection").style.display = "block";
      container.querySelector("#history-timeline").innerHTML = `
        <div style="text-align: center; color: var(--text-muted); padding: 16px; font-size: 12px;">
          クライアントを選択すると対応履歴が表示されます
        </div>
      `;
      return;
    }

    container.querySelector("#detail-panel").style.display = "block";
    container.querySelector("#no-selection").style.display = "none";

    container.querySelector("#detail-name").textContent = client.クライアント名 || "—";
    container.querySelector("#detail-industry").textContent = client.業種 || "—";
    container.querySelector("#detail-rep").textContent = client.代表者名 || "—";
    container.querySelector("#detail-email").textContent = client.メールアドレス || "—";
    container.querySelector("#detail-phone").textContent = client.電話番号 || "—";
    container.querySelector("#detail-contract").textContent = client.契約状況 || "—";
    container.querySelector("#detail-revenue").textContent = `¥${(client.推定売上額 || 0).toLocaleString()}`;
    container.querySelector("#detail-notes").textContent = client.備考 || "—";

    // 対応履歴タイムラインを描画
    const histories = allHistories.filter(h => h.クライアントID === client.id);
    if (histories.length === 0) {
      container.querySelector("#history-timeline").innerHTML = `
        <div style="text-align: center; color: var(--text-muted); padding: 16px; font-size: 12px;">
          対応履歴がありません
        </div>
      `;
    } else {
      container.querySelector("#history-timeline").innerHTML = histories
        .sort((a, b) => new Date(b.対応日時) - new Date(a.対応日時))
        .map(h => `
          <div style="padding: 8px; border-left: 2px solid #d4a574; margin-bottom: 8px; background: rgba(0,0,0,0.2); border-radius: 3px;">
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">
              ${new Date(h.対応日時).toLocaleString('ja-JP')}
            </div>
            <div style="font-size: 12px; font-weight: 600; color: #d4a574; margin-bottom: 3px;">
              ${h.対応種別 || "—"}
            </div>
            <div style="font-size: 12px; line-height: 1.4; color: var(--text);">
              ${h.対応内容 || "—"}
            </div>
            ${h.成果 ? `<div style="font-size: 11px; color: #c41e3a; margin-top: 4px;">成果: ${h.成果}</div>` : ""}
          </div>
        `).join("");
    }
  }

  function updateKPIs() {
    // 受注数（今月）
    const thisMonth = new Date();
    const monthStart = new Date(thisMonth.getFullYear(), thisMonth.getMonth(), 1);
    const monthOrders = allOrders.filter(o => new Date(o.受注日) >= monthStart);
    container.querySelector("[data-testid='kpi-orders']").textContent = monthOrders.length;

    // 売上予測（今月）
    const revenue = monthOrders.reduce((sum, o) => sum + (o.受注金額 || 0), 0);
    container.querySelector("[data-testid='kpi-revenue']").textContent = `¥${revenue.toLocaleString()}`;

    // アクティブ案件
    const activeProjects = allProjects.filter(p => ["新規", "進行中", "提案済み"].includes(p.ステータス));
    container.querySelector("[data-testid='kpi-projects']").textContent = activeProjects.length;

    // 対応待ちクライアント（最終接触が7日以上前）
    const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
    const pendingClients = allClients.filter(c => !c.最終接触日 || new Date(c.最終接触日) < sevenDaysAgo);
    container.querySelector("[data-testid='kpi-pending']").textContent = pendingClients.length;

    // 案件進捗ボード
    container.querySelector("#project-new").textContent = allProjects.filter(p => p.ステータス === "新規").length;
    container.querySelector("#project-progress").textContent = allProjects.filter(p => p.ステータス === "進行中").length;
    container.querySelector("#project-proposed").textContent = allProjects.filter(p => p.ステータス === "提案済み").length;
    container.querySelector("#project-won").textContent = allProjects.filter(p => p.ステータス === "受注").length;
    container.querySelector("#project-lost").textContent = allProjects.filter(p => p.ステータス === "失注").length;
  }

  // ===== 2. 初期データ読み込み =====
  Promise.all([
    window.aivicApi.list(TABLE_CLIENT),
    window.aivicApi.list(TABLE_HISTORY),
    window.aivicApi.list(TABLE_PROJECT),
    window.aivicApi.list(TABLE_ORDER)
  ]).then(([clients, histories, projects, orders]) => {
    allClients = clients || [];
    allHistories = histories || [];
    allProjects = projects || [];
    allOrders = orders || [];

    renderClients(allClients);
    updateKPIs();
  });

  // ===== 3. 検索・フィルター =====
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    const statusFilter = container.querySelector("#filter-status").value;

    let filtered = allClients;

    if (keyword) {
      filtered = filtered.filter(c =>
        (c.クライアント名 || "").toLowerCase().includes(keyword) ||
        (c.業種 || "").toLowerCase().includes(keyword)
      );
    }

    if (statusFilter) {
      filtered = filtered.filter(c => c.ステータス === statusFilter);
    }

    renderClients(filtered);
  });

  // ===== 4. クライアント行クリック（詳細表示） =====
  container.addEventListener("click", (e) => {
    const row = e.target.closest(".client-row");
    if (row) {
      selectedClientId = row.dataset.id;
      const client = allClients.find(c => c.id === selectedClientId);
      renderDetailPanel(client);

      // 行のハイライト
      container.querySelectorAll(".client-row").forEach(r => r.style.background = "");
      row.style.background = "rgba(212, 165, 116, 0.15)";
    }
  });

  // ===== 5. ボタンアクション =====
  container.querySelector("[data-testid='add-client-button']").addEventListener("click", () => {
    window.showScreen("scr-1781408824557"); // クライアント詳細情報画面
  });

  container.querySelector("[data-testid='add-history-button']").addEventListener("click", () => {
    window.showScreen("scr-1781408865891"); // 対応履歴登録画面
  });

  container.querySelector("[data-testid='add-project-button']").addEventListener("click", () => {
    window.showScreen("scr-1781408904580"); // 案件登録画面
  });

  container.querySelector("[data-testid='edit-client-button']").addEventListener("click", () => {
    if (selectedClientId) {
      window.showScreen("scr-1781408824557"); // クライアント詳細情報画面
    }
  });

  container.querySelector("[data-testid='view-detail-button']").addEventListener("click", () => {
    if (selectedClientId) {
      window.showScreen("scr-1781408840123"); // 対応履歴・対応方針管理画面
    }
  });
}
